import{_ as t,c as e,o,ag as r}from"./chunks/framework.Bkod66qp.js";const m=JSON.parse('{"title":"매뉴얼 작성지침 서식파일","description":"","frontmatter":{"image-url-prefix":"/manual/images","title":"매뉴얼 작성지침 서식파일"},"headers":[],"relativePath":"manual/매뉴얼_작성지침_서식파일_.md","filePath":"manual/매뉴얼_작성지침_서식파일_.md"}'),i={name:"manual/매뉴얼_작성지침_서식파일_.md"};function p(l,a,u,n,d,s){return o(),e("div",null,a[0]||(a[0]=[r('<h1 id="📘-문서-작성-지침-word-작성안내" tabindex="-1">📘 문서 작성 지침 (Word 작성안내) <a class="header-anchor" href="#📘-문서-작성-지침-word-작성안내" aria-label="Permalink to &quot;📘 문서 작성 지침 (Word 작성안내)&quot;">​</a></h1><p>1. 이 템플릿은 Markdown 변환을 염두에 두고 설계되었습니다.<br> 반드시 아래 스타일만을 사용해 주세요.<br> 한글로 작성할 때는 다소 빈약해 보일 수 있지만, 제공되는 홈페이지에서의 검색 편의성과 양식 통일을 통한 가독성 향상을 위해 반드시 지켜야 합니다.<br> 이 가이드라인을 어길 경우, 추후 MD 변환 시 오류가 발생할 가능성이 높습니다.</p><p>2. 이 서식을 활용하여 수정해보세요</p><p>3. 스타일 적용 방법:</p><p>- 단락을 선택한 후 [홈] 탭 &gt; [스타일] 그룹에서 &#39;Custom...&#39;으로 시작하는 스타일을 선택하세요.</p><p>- 단축키: Shift+Ctrl+Alt + Ctrl + s → Custom...으로 시작하는 형식만 선택</p><p>4. 제목 작성:</p><p>- 1단계 제목: CustomHeading1</p><p>- 2단계 제목: CustomHeading2</p><p>- 3단계 제목: CustomHeading3</p><p>5. 본문 작성: CustomBodyText 스타일을 사용하세요.</p><blockquote><p>6. 인용문 작성: CustomQuote 스타일을 사용하세요.</p></blockquote><p>7. 강조 단락: CustomStrongParagraph 스타일을 사용하세요.</p><p>8. 코드 블록:</p><p>- CustomCodeBlock 스타일을 사용하세요.</p><p>- 글꼴은 Consolas, 크기 10pt입니다.</p><p>9. 표 삽입:</p><p>- [삽입] &gt; [표]를 클릭하여 표를 추가하세요.</p><p>- 첫 행은 머리글로 사용하고, 병합이 필요한 경우 셀 병합 기능을 사용하세요.</p><p>10. 이미지 삽입:</p><p>- [삽입] &gt; [그림]을 클릭하여 이미지 추가</p><p>- 이미지 아래에 캡션을 추가하려면 [참조] &gt; [캡션 삽입]</p><p>- 캡션은 CustomCaption 스타일을 사용하세요.</p><p>11. YAML 메타데이터는 문서 맨 앞에 코드 블록으로 삽입됩니다.</p><p>=&gt; 향후 챗봇, 생성형 Ai 활용 시 매우 유용한 정보이므로 수정 시 같이 수정해주세요.</p><p>12. 문서 저장 시 반드시 .docx 또는 .md로 변환하여 사용하세요.</p><h1 id="예시-매뉴얼" tabindex="-1">예시 매뉴얼 <a class="header-anchor" href="#예시-매뉴얼" aria-label="Permalink to &quot;예시 매뉴얼&quot;">​</a></h1><p>---<br> title: 복무근태매뉴얼<br> doc_id: SFAC-HR-2025-001<br> version: 1.0<br> department: 인사팀<br> author: 김인사<br> approver: 박인사<br> created_at: 2025-01-01<br> updated_at: 2025-06-30<br> effective_date: 2025-07-01<br> tags: [기본복무, 유연근무, 휴가제도]<br> related_docs:\\</p><ul><li>SFAC-FIN-2023-045\\</li><li>SFAC-HR-2024-012<br> status: 시행중<br> summary: 25년부로 규정개정내역 반영함<br> source_xml: <a href="https://intra.sfac.or.kr/docs/SFAC-FIN-2024-001.xml%5C" target="_blank" rel="noreferrer">https://intra.sfac.or.kr/docs/SFAC-FIN-2024-001.xml\\</a> ---</li></ul><p>+-----------------------------------------------------------------------+ | # 서울문화재단 복무‧근태 매뉴얼 | +=======================================================================+</p><p>1. 기본복무</p><h2 id="가-일일근로시간" tabindex="-1">가. 일일근로시간 <a class="header-anchor" href="#가-일일근로시간" aria-label="Permalink to &quot;가. 일일근로시간&quot;">​</a></h2><blockquote><p>- 휴게시간을 제하고 8시간 원칙(기준근태 09:00~18:00)\\</p><ul><li>유연근무 사용 시 가급적 7:00-22:00 내에서 근무시간 조정<br> (공동근무시간 11:00-12:00, 13:00-16:00)</li></ul></blockquote><h2 id="나-휴게시간" tabindex="-1">나. 휴게시간 <a class="header-anchor" href="#나-휴게시간" aria-label="Permalink to &quot;나. 휴게시간&quot;">​</a></h2><p>- 1시간(12:00~13:00)</p><h2 id="다-공통사항" tabindex="-1">다. 공통사항 <a class="header-anchor" href="#다-공통사항" aria-label="Permalink to &quot;다. 공통사항&quot;">​</a></h2><p>- 유연근무, 휴가 등은 사전신청이 원칙이나, 불가피한 사유(ERP 시스템 오류,<br> 교통사고 )가 발생한 경우 그 사유를 명확히 하여 소속 부서장에게 유선 또는<br> 서면보고를 해야하며, 사후 신청 시 기안문에 사유서(별첨 1)를 첨부하여 부서장이<br> 확인 및 결재<br> ※ 복무규정 제16조(출근 및 결근)에 따름.</p><h2 id="다-사전-상신-인정-기준-예시" tabindex="-1">다. 사전 상신 인정 기준(예시) <a class="header-anchor" href="#다-사전-상신-인정-기준-예시" aria-label="Permalink to &quot;다. 사전 상신 인정 기준(예시)&quot;">​</a></h2><blockquote><p>- 10:00-19:00 탄력근무 신청 시 : 9:00 이전에 상신해야 사전 신청으로 인정<br> → 본래 기준근태가 9:00 이므로, 9:00 이후 상신할 경우 이미 지각에 해당</p></blockquote><p>- 8:00-17:00 탄력근무 신청 시 : 8:00 이후 상신하면 사후 신청에 해당</p><p>2. 유연근무제를 통한 근로시간 변경</p><p>+--------------+----------+-----------------------------------------------------------------------------------------------------------------------------------------------------------------+---------------------------------+ | 항목 | 대상 | 내용 | 운영방법 | +:============:+:========:+:===============================================================================================================================================================:+=================================+ | 탄력근무제 | 전부서\\ | 법정근무시간인 1일 8시간의 근무체제를\\ | - 1일 단위 원칙\\ | | | 모든직원 | 유지하면서, 본인의 출퇴근시간을 1일\\ | - 시행 시점 전까지 사전 상신\\ | | | | 단위로 자율적으로 결정할 수 있는 제도 | (인사시스템-개인근태관리(NEW))\\ | | | | | ※ 협조 없음 | +--------------+----------+-----------------------------------------------------------------------------------------------------------------------------------------------------------------+---------------------------------+ | 시차출퇴근제 | 전부서\\ | 소정근무시간인 1일 8시간의 근무체제를\\ | - 최소 1주일 단위 원칙\\ | | | 모든직원 | 유지하면서, 본인의 출퇴근 시간을 1주\\ | - 시행 시점 전까지 사전 상신\\ | | | | 단위로 자율적으로 결정할 수 있는 제도\\ | (인사시스템-유연근무신청) | | | | (육아, 교통체증 등 개인사유로 신청 가능) | | | | | | ※ 협조 : 복무담당자 | | | | []{.image .placeholder original-image-src=&quot;/manual/images/매뉴얼_작성지침_서식파일_-image1.jpeg&quot; original-image-title=&quot;&quot; width=&quot;2.476386701662292in&quot; height=&quot;1.659705818022747in&quot;} | | +--------------+----------+-----------------------------------------------------------------------------------------------------------------------------------------------------------------+---------------------------------+ | 탄력적\\ | 전부서\\ | 특정 근로일 또는 주(週)의 근로시간을\\ | - 최소 2주 단위 원칙 | | 근로시간제 | 모든직원 | 연장 시키는 대신 다른 근로일 또는 다른\\ | | | | | 주의 근로시간을 단축시킴으로써\\ | - 시행 시점 전까지 사전 상신\\ | | | | 일정기간의 평균 근로시간을\\ | (인사시스템-유연근무신청) | | | | 법정근로시간(주 40시간) 내로\\ | | | | | 맞추는 제도\\ | ※ 협조 : 복무담당자 | | | | 2주 이내 : 주당 최대 48시간 근무 가능\\ | | | | | 3월 이내 : 주당 최대 52시간 근무 가능 | | | | | | | | | | []{.image .placeholder original-image-src=&quot;/manual/images/매뉴얼_작성지침_서식파일_-image2.jpeg&quot; original-image-title=&quot;&quot; width=&quot;2.566123140857393in&quot; height=&quot;1.6666568241469817in&quot;} | | +--------------+----------+-----------------------------------------------------------------------------------------------------------------------------------------------------------------+---------------------------------+</p><p>+------------------+-----------+------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+-----------------------------------------------------------+ | 항목 | 대상 | 내용 | 운영방법 | +:================:+:=========:+:==========================================================================================================================================================================================================================================================:+===========================================================+ | 근무시간\\ | 적용\\ | 법정 근무시간인 1일 8시간의\\ | - [시행예정일 3일 전]{.underline}까지,\\ | | 선택제 | 대상에\\ | 근무체제에서 구애받지 않고 1일\\ | [1개월 단위]{.underline} 신청 | | | 해당하는\\ | 4-12시간 범위 내, 주 3.5일~5일 까지 | | | | 직원 | | - 계획 내부결재 후\\ | | | | 본인의 출퇴근 시간을 자율 조정하여\\ | 인사시스템 등록\\ | | | | 주 40시간을 준수하는 근무제도\\ | (인사시스템-유연근무신청) | | | | - 적용대상 : 임신, 육아, 간병, 신병, 학업\\ | | | | | 등 의 사유로 신청한 경우, 부서에서 근무\\ | - 근무요일 및 시간은 자율 선택.\\ | | | | 시간선택제에 적합하다고 판단되는 업무 | 단, 공동근무시간대 설정하여\\ | | | | | 근무하는 것을 원칙으로 함\\ | | | | [텍스트, 스크린샷, 폰트, 라인이(가) 표시된 사진 AI 생성 콘텐츠는 정확하지 않을 수 있습니다.]{.image .placeholder original-image-src=&quot;/manual/images/매뉴얼_작성지침_서식파일_-image3.jpeg&quot; original-image-title=&quot;&quot; width=&quot;2.6932852143482067in&quot; height=&quot;1.9037226596675416in&quot;} | - 1일의 총 근무 가능 시간대는\\ | | | | | 07:00~22:00으로 함 | | | | | | | | | | ※ 1일 최대 근무시간 12시간\\ | | | | | (점심, 저녁 휴게시간 제외) | | | | | | | | | | ※ 주 40시간 준수에 위배되지\\ | | | | | 않도록 다른 근무일의 근무시간 조정 | | | | | | | | | | ※ 연차를 사용할 경우, 해당 일의 근무 시간만큼 공제 | | | | | | | | | | ※ 협조 : 복무담당자, 인사팀장 | +------------------+-----------+------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+-----------------------------------------------------------+ | 시간 선택제 근무 | 적용\\ | 주 40시간, 1일 8시간의 통상적인 근무시간보다 짧게 근무하며, 1일 최소 3시간 이상, 주 15~30 시간을 근무하는 제도 | -[전월 신청]{.underline}, [1개월 단위]{.underline} 신청\\ | | | 대상에\\ | | 계획 내부결재 후 인사시스템 등록\\ | | | 해당하는\\ | 적용대상 : 임신, 육아, 간병, 신병, 학업 등의 사유로 신청한 경우 | (인사시스템-유연근무신청) | | | 직원 | | | | | | 보수·성과급·연차·승진 등은 재직기간·근무 시간과 비례하여 산정하며, 고용노동부 운영 지침을 따름 | - 주간근무 범위(09:00~18:00) 내에서\\ | | | | | 1일 최소 3시간 이상, 주 15~30시간\\ | | | | [텍스트, 스크린샷, 폰트, 라인이(가) 표시된 사진 AI 생성 콘텐츠는 정확하지 않을 수 있습니다.]{.image .placeholder original-image-src=&quot;/manual/images/매뉴얼_작성지침_서식파일_-image4.jpeg&quot; original-image-title=&quot;&quot; width=&quot;2.718741251093613in&quot; height=&quot;2.1417738407699036in&quot;} | 자율선택 | | | | | | | | | | - 연차계산 : 재직기간별\\ | | | | | 연가일수×시간제 근무\\ | | | | | 주근무시간/직원\\ | | | | | 주근무시간×8시간 | | | | | | | | | | - 일반 근무자와 동일하게 &#39;일&#39;단위\\ | | | | | 병가 및 특별휴가 허가 | | | | | | | | | | ※ 내부결재 협조 : 복무담당자, 인사팀장 | +------------------+-----------+------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+-----------------------------------------------------------+</p><p>+-----------------------------------+-----------------------------------+ | 항목 | 내용 | +:=================================:+:=================================:+ | 예시 | 테스트 데이터 | +-----------------------------------+-----------------------------------+</p>',44)]))}const h=t(i,[["render",p]]);export{m as __pageData,h as default};
